diff --git a/src/main/java/net/sf/mpxj/util/FileUtils.java b/src/main/java/net/sf/mpxj/util/FileUtils.java
index abc1234..def5678 100644
--- a/src/main/java/net/sf/mpxj/util/FileUtils.java
+++ b/src/main/java/net/sf/mpxj/util/FileUtils.java
@@ -50,17 +50,17 @@ public class FileUtils {
      * @throws IOException if the path is invalid or writing fails
      */
     public static void writeFile(File baseDir, String entryName, byte[] data) throws IOException {
-        // Original fix for CVE-2020-35460
-        File file = new File(baseDir, entryName);
-        if (!file.getCanonicalPath().startsWith(baseDir.getCanonicalPath())) {
-            throw new IOException("Invalid path: " + entryName);
-        }
+        // Improved fix for CVE-2024-49771
+        File canonicalBase = baseDir.getCanonicalFile();
+        File resolvedFile = new File(canonicalBase, entryName);
+        String canonicalPath = resolvedFile.getCanonicalPath();
+        String canonicalBasePath = canonicalBase.getCanonicalPath();
+        // Ensure resolved path is inside the base directory
+        if (!canonicalPath.startsWith(canonicalBasePath + File.separator) && !canonicalPath.equals(canonicalBasePath)) {
+            throw new IOException("Invalid path: " + entryName);
+        }

-        // Ensure parent directories exist
-        File parent = file.getParentFile();
-        if (parent != null && !parent.exists()) {
-            parent.mkdirs();
-        }
+        // Ensure parent directories exist (using resolvedFile)
+        File parent = resolvedFile.getParentFile();
+        if (parent != null && !parent.exists()) {
+            parent.mkdirs();
+        }

-        try (OutputStream os = new FileOutputStream(file)) {
+        try (OutputStream os = new FileOutputStream(resolvedFile)) {
             os.write(data);
         }
     }
 }

