+/**
+ * Validate that a URL uses only allowed protocols (http or https).
+ * Throws an error if the URL is invalid or uses a disallowed protocol.
+ * @param {string} url - The URL to validate.
+ * @returns {string} The validated URL.
+ */
+function validateUrl(url) {
+    let parsed;
+    try {
+        parsed = new URL(url);
+    } catch (err) {
+        throw new Error(`Invalid URL: ${err.message}`);
+    }
+
+    const allowedProtocols = ['http:', 'https:'];
+    if (!allowedProtocols.includes(parsed.protocol)) {
+        throw new Error(`URL protocol "${parsed.protocol}" is not allowed. Only HTTP and HTTPS are permitted.`);
+    }
+
+    return url;
+}
+
+module.exports = {
+    validateUrl,
+};
