index a1b2c3d..e4f5g6h 100644
--- a/lib/update-verifier.js
+++ b/lib/update-verifier.js
@@ -1,5 +1,6 @@
 const fs = require('fs');
 const path = require('path');
+const crypto = require('crypto');
 const { verifySignature } = require('./signature-utils');

 /**
@@ -15,6 +16,8 @@ function verifyUpdatePackage(packagePath) {
   if (!fs.existsSync(manifestPath)) {
     throw new Error('Update package manifest not found');
   }
+  // Verify the manifest signature and integrity of all files
+  verifyManifestIntegrity(packagePath, manifestPath);

   // Existing signature verification for the main executable
   const mainExecutable = path.join(packagePath, 'app', 'main.exe');
@@ -24,4 +27,29 @@ function verifyUpdatePackage(packagePath) {
   return true;
