+/**
+ * Verifies that all files in the update package match the hashes in the
+ * signed manifest. This prevents attackers from replacing files after
+ * the package was signed.
+ */
+function verifyManifestIntegrity(packagePath, manifestPath) {
+  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
+  if (!manifest.signature || !manifest.files) {
+    throw new Error('Invalid manifest format');
+  }
+  // Verify the manifest's own signature (assumes public key is embedded or known)
+  const manifestData = JSON.stringify(manifest.files);
+  if (!verifySignature(manifestData, manifest.signature)) {
+    throw new Error('Manifest signature verification failed');
+  }
+  // Check each file's hash
+  for (const [filePath, expectedHash] of Object.entries(manifest.files)) {
+    const fullPath = path.join(packagePath, filePath);
+    const fileBuffer = fs.readFileSync(fullPath);
+    const actualHash = crypto.createHash('sha256').update(fileBuffer).digest('hex');
+    if (actualHash !== expectedHash) {
+      throw new Error(`File integrity check failed for ${filePath}`);
+    }
+  }
+}
